[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$StoryPath)
$ErrorActionPreference='Stop';$script:RootSchema=Get-Content (Join-Path $PSScriptRoot '..\schemas\portable-project-story.schema.json') -Raw|ConvertFrom-Json;$x=Get-Content (Join-Path $StoryPath 'project-story.json') -Raw|ConvertFrom-Json;$script:InvokeSchema={param([AllowNull()]$v,$s,$p).(Join-Path $PSScriptRoot 'Invoke-PortableSchemaValidation.ps1') -Value $v -Schema $s -RootSchema $script:RootSchema -Path $p};. (Join-Path $PSScriptRoot 'Invoke-PortableSchemaValidation.ps1') -Value $x -Schema $script:RootSchema -RootSchema $script:RootSchema -Path 'root';Write-Host 'PASS: Portable recursive schema validation.'
